    if (dt > 0.1f)
        dt = 0.1f;
    if (IsControllerDisconnected() && !m_pFrontEndManager->IsBlockingControllerMessage()) {
        if (!NUISystem::CManager::GetInstance()->m_errorMessageShowing)
