long CNOVI_Villager::GetVillagerSpeechIndex(long count)
{
    while (!IsDone()) {
        long index = rand() % count;
        if (index != ParentClass->lastVillagerSpeechIdx) {
            if (IsDone())
                return 0;
            ParentClass->lastVillagerSpeechIdx = index;
            return IsDone() ? 0 : index;
        }
        Game->Update();
    }
    return 0;
}

